<script setup lang="ts">
import {computed,onMounted} from 'vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import {useTransferBackupsV2Store} from './transfer-backups-v2'
const props=withDefaults(defineProps<{workspace?:boolean;dialogOwner?:boolean}>(),{workspace:true,dialogOwner:false})
const backups=useTransferBackupsV2Store(),session=computed(()=>backups.active)
const labels:Record<string,string>={channels:'渠道与模型',templates:'模型模版',preferences:'桌面偏好',extensions:'扩展设置',webdav:'导入的连接',accounts:'账户信息',mcp:'MCP定义'}
const label=(value:string)=>value.startsWith('skill:')?'Skill · '+value.slice(6):labels[value]??value
const reasons:Record<string,string>={scope_restore_stale:'目标内容已有后续修改，未覆盖当前内容；原恢复计划保持。',scope_restore_source_stale:'原备份来源已有变化，未替换当前内容。',scope_restore_dependency:'所选范围缺少完整精确依赖，未自动扩大恢复；请重新核对。',scope_restore_unsaved_draft:'当前存在模型编辑会话或未保存草稿，请先处理后重新核对。',scope_restore_not_ready:'原备份尚未具备安全恢复条件，未开始恢复。',scope_backup_corrupt:'范围备份记录未通过校验，当前内容保持。',scope_restore_participant_failed:'部分范围未完成恢复；已完成项保持，请核对后继续原恢复。'}
const explain=(value:string)=>reasons[value]?reasons[value]+'（'+value+'）':value
function toggle(group:string,checked:boolean){const groups=session.value?.groups??[];backups.setGroups(checked?[...groups,group]:groups.filter(value=>value!==group))}
onMounted(()=>{if(props.workspace)void backups.load()})
</script>
<template>
 <section :class="{'transfer-backups':workspace}" aria-label="同步与导入前范围备份">
  <template v-if="workspace"><div class="transfer-backup-head"><div><h3>同步与导入前备份</h3><p>恢复原操作所选资源在更新前的内容；后续相同字段如有修改，需先核对。</p></div><UiButton variant="ghost" size="sm" :disabled="backups.loading||backups.busy" @click="backups.load()">刷新记录</UiButton></div>
  <p v-if="backups.loading" role="status">正在读取本版范围备份记录…</p><p v-if="backups.listError" class="model-error" role="alert">{{explain(backups.listError)}} {{backups.rows.length?'下方保留上次记录，请刷新核对。':'尚无可用备份目录，未按空记录处理。'}}</p><p v-if="!backups.rows.length&&!backups.loading&&!backups.listError" class="model-muted">尚无更新前范围备份。</p>
  <ul><li v-for="row in backups.rows" :key="row.id"><div><span>{{row.groups.map(label).join('、')}}</span><small v-if="!row.enabled">原操作未启用范围备份</small><small v-else-if="!row.ready">原备份尚未具备安全恢复条件</small><small v-if="backups.sessions[row.id]?.receipt?.status==='partial'">原恢复部分完成，可继续核对</small><small v-if="backups.sessions[row.id]?.receipt?.status==='applied'">已有恢复回执</small></div><UiButton size="sm" :disabled="backups.busy||!row.enabled||!row.ready" @click="backups.choose(row)">{{backups.sessions[row.id]?.attempted?'查看原恢复':'恢复所选范围'}}</UiButton></li></ul>
  <section v-if="backups.operations.length||backups.operationsError" aria-label="此前范围恢复"><h3>此前恢复操作</h3><p>选择后读取该计划的原始范围与回执。部分完成可继续原操作；已完成的记录只供查看，不重复覆盖后来内容。</p><p v-if="backups.operationsError" class="model-error" role="alert">{{explain(backups.operationsError)}} 已保留此前目录，未替换为其他恢复计划。</p><UiButton v-if="backups.operationsError" :disabled="backups.operationsLoading||backups.busy" @click="backups.loadOperations()">重新读取恢复记录</UiButton><ul><li v-for="operation in backups.operations" :key="operation.restoreId"><div><span>{{operation.groups.map(label).join('、')}}</span><small>{{operation.receipt?.status==='applied'?'已有完成回执':operation.receipt?.status==='partial'?'部分完成':'尚无完成回执'}}</small><code>{{operation.restoreId}}</code></div><UiButton size="sm" :disabled="backups.busy||backups.operationsLoading" @click="backups.openOperation(operation)">{{operation.receipt?.status==='applied'?'查看恢复回执':'继续此前恢复'}}</UiButton></li></ul></section>
  </template><UiDialog v-if="dialogOwner" :open="backups.open&&!!session" title="恢复更新前备份" :busy="backups.busy" wide panel-class="transfer-backup-restore-v2" @close="backups.close()">
   <template v-if="session"><p>选择原备份已有的范围，确认后恢复所选保存内容。未选范围保持；依赖不完整时会停止，不自动扩大恢复。</p><div class="transfer-restore-scope"><label v-for="group in session.availableGroups" :key="group"><input type="checkbox" :aria-label="'恢复范围 '+label(group)" :checked="session.groups.includes(group)" :disabled="backups.busy||session.attempted" @change="toggle(group,($event.target as HTMLInputElement).checked)" />{{label(group)}}</label></div>
   <p v-if="!session.groups.length" class="model-muted">请选择至少一个范围。</p><p>确认恢复时会结束未修改的模型编辑会话；有未保存输入时将停止，不会清除编辑。</p><p v-if="backups.checking" role="status">正在核对原备份、所选目标及当前保存内容…</p><p v-if="backups.restoring" role="status">正在核对并执行原恢复，请等待实际回执。</p><p v-if="session.attempted&&!session.receipt" role="status">原恢复已发出，结果尚未确认。再次核对将继续原恢复标识，范围保持固定。</p>
   <template v-if="session.receipt"><h3>{{session.receipt.status==='applied'?'所选范围已恢复':'原恢复部分完成'}}</h3><p v-if="session.receipt.status==='partial'" role="status">已完成项保持，未完成项仍需核对；尚未标记全部恢复成功。</p><ul class="transfer-restore-progress"><li v-for="group in session.receipt.groups" :key="group"><span>{{label(group)}}</span><span>{{session.receipt.completedGroups.includes(group)?'已核验恢复':'尚未完成'}}</span></li></ul></template>
   <p v-if="backups.confirmationStale" class="model-error" role="alert">当前编辑或来源已变化。请先处理未保存输入，再重新核对；本次恢复尚未发出。</p><p v-if="session.error" class="model-error" role="alert">{{explain(session.error)}}</p><p v-if="session.refreshError" class="model-error" role="alert">{{session.refreshError}} 原恢复回执保持，读取界面结果不会重新执行恢复。</p><details v-if="session.preview"><summary>原操作与本次恢复标识</summary><p>原操作 {{session.originalOperationId}}</p><p>本次恢复 {{session.preview.restoreId}}</p><p>已核对范围：{{session.preview.groups.map(label).join('、')}}</p></details></template>
   <template #actions="{close}"><UiButton :disabled="backups.busy" @click="close">{{session?.attempted?'关闭':'取消'}}</UiButton><UiButton v-if="session&&!session.attempted&&(session.error||!session.preview||backups.confirmationStale)" :disabled="backups.busy||!session.groups.length" @click="backups.preview()">重新核对</UiButton><UiButton v-if="session?.receipt" :disabled="backups.busy" @click="backups.refreshSaved()">{{session.refreshError?'重新读取恢复结果':'读取当前保存结果'}}</UiButton><UiButton v-if="session?.receipt?.status!=='applied'" variant="primary" :disabled="!backups.canRestore" :loading="backups.restoring" @click="backups.restore()">{{session?.attempted?'核对并继续原恢复':'确认恢复'}}</UiButton></template>
  </UiDialog>
 </section>
</template>
<style scoped>
.transfer-backups{margin-top:24px;border-top:1px solid var(--border);padding-top:20px}.transfer-backup-head,.transfer-backups li,.transfer-restore-progress li{display:flex;justify-content:space-between;align-items:center;gap:16px}.transfer-backups ul,.transfer-restore-progress{list-style:none;padding:0}.transfer-backups li,.transfer-restore-progress li{padding:12px 0;border-bottom:1px solid var(--border)}.transfer-backups p,.model-muted{color:var(--muted);font-size:var(--text-caption);line-height:1.6}.transfer-backups small{display:block;color:var(--muted)}.transfer-restore-scope{display:grid;gap:10px;margin:16px 0}.transfer-restore-scope label{display:flex;align-items:center;gap:8px}.model-error,.transfer-backups .model-error{color:var(--red)}p,span,small{overflow-wrap:anywhere}h3{font-size:var(--text-body)}@media(max-width:620px){.transfer-backup-head,.transfer-backups li{align-items:flex-start;flex-direction:column}}
</style>
